@OptIn(ExperimentalContracts::class)
fun isValid(s: String?): Boolean {
    contract { returns(true) implies (s != null) }
    return !s.isNullOrBlank()
}

inline fun repeatTwice(block: () -> Unit) {
    block()
    block()
}

fun test(): String {
    repeatTwice {
        print("A")
        repeatTwice {
            print("B")
            return "done"
        }
    }
    return "end"
}

fun main() {
    println(test())
}
